//! Picked sub-entity ↔ persistent [`TopoRef`] (spec §8; S01 requests R1 and R2).
//!
//! **Provisional.** S01's `naming::topo_ref_at` (R1) and `Evaluated::resolve_for_display` (R2)
//! come with DOC-06, which is not done. Until then this module:
//! - uses the body's [`BodyNaming`](amg_doc::BodyNaming) when it has a name at the picked index
//!   (resolution: the index of that name, exact match only);
//! - names a mesh triangle, triangle edge or vertex by its index, generated by the body's
//!   creating feature (`NameSeg::Generated` with role `ui.mesh.triangle` / `ui.mesh.edge` /
//!   `ui.mesh.vertex`), plus a [`GeomFingerprint`] of the element. Such a reference resolves
//!   only while the element at that index still has the same fingerprint, so an edited mesh
//!   drops it instead of silently pointing at another triangle (S01 hard rule).
//!
//! Mesh sub-ids: a triangle is its face index, a triangle edge is `3 × triangle + corner` (the
//! edge from corner `k` to corner `k + 1`), a vertex is the mesh vertex index.

use std::borrow::Cow;

use amg_core::{Aabb3, Point3};
use amg_doc::stub::IndexedMesh;
use amg_doc::{
    BodyGeom, BodyId, Evaluated, GeomClass, GeomFingerprint, NameSeg, Role, TopoKind, TopoName,
    TopoRef,
};

/// Role tag of a mesh triangle name.
pub const MESH_TRIANGLE_ROLE: &str = "ui.mesh.triangle";
/// Role tag of a mesh triangle-edge name.
pub const MESH_EDGE_ROLE: &str = "ui.mesh.edge";
/// Role tag of a mesh vertex name.
pub const MESH_VERTEX_ROLE: &str = "ui.mesh.vertex";

fn role_tag(kind: TopoKind) -> Option<&'static str> {
    match kind {
        TopoKind::Face => Some(MESH_TRIANGLE_ROLE),
        TopoKind::Edge => Some(MESH_EDGE_ROLE),
        TopoKind::Vertex => Some(MESH_VERTEX_ROLE),
        TopoKind::FaceGroup => None,
    }
}

/// The corner positions of mesh edge `edge` (`3 × triangle + corner`).
pub fn mesh_edge(mesh: &IndexedMesh, edge: u32) -> Option<(Point3, Point3)> {
    let tri = mesh.tris.get((edge / 3) as usize)?;
    let k = (edge % 3) as usize;
    let a = *mesh.positions.get(tri[k] as usize)?;
    let b = *mesh.positions.get(tri[(k + 1) % 3] as usize)?;
    Some((a, b))
}

/// Fingerprint of a mesh element (`None` for an index out of range).
pub fn mesh_fingerprint(mesh: &IndexedMesh, kind: TopoKind, index: u32) -> Option<GeomFingerprint> {
    match kind {
        TopoKind::Face => {
            let tri = mesh.tris.get(index as usize)?;
            let p = tri.map(|i| mesh.positions.get(i as usize).copied());
            let [Some(a), Some(b), Some(c)] = p else {
                return None;
            };
            let n = (b - a).cross(c - a);
            Some(GeomFingerprint {
                class: GeomClass::Plane,
                measure: 0.5 * n.length(),
                centroid: (a + b + c) / 3.0,
                axis: Some(n.normalize_or_zero()),
                bbox: Aabb3::from_points([a, b, c]),
            })
        }
        TopoKind::Edge => {
            let (a, b) = mesh_edge(mesh, index)?;
            Some(GeomFingerprint {
                class: GeomClass::Line,
                measure: (b - a).length(),
                centroid: (a + b) * 0.5,
                axis: Some((b - a).normalize_or_zero()),
                bbox: Aabb3::from_points([a, b]),
            })
        }
        TopoKind::Vertex => {
            let p = *mesh.positions.get(index as usize)?;
            Some(GeomFingerprint {
                class: GeomClass::Point,
                measure: 0.0,
                centroid: p,
                axis: None,
                bbox: Aabb3::from_points([p]),
            })
        }
        TopoKind::FaceGroup => None,
    }
}

fn provisional_name(body: BodyId, kind: TopoKind, index: u32) -> Option<TopoName> {
    Some(TopoName::new(vec![NameSeg::Generated {
        feature: body.origin,
        role: Role {
            tag: Cow::Borrowed(role_tag(kind)?),
            index,
        },
        from: None,
    }]))
}

/// The index a provisional name stands for, if `name` is one for `body` and `kind`.
fn provisional_index(name: &TopoName, body: BodyId, kind: TopoKind) -> Option<u32> {
    let [
        NameSeg::Generated {
            feature,
            role,
            from: None,
        },
    ] = name.segments()
    else {
        return None;
    };
    (*feature == body.origin && Some(role.tag.as_ref()) == role_tag(kind)).then_some(role.index)
}

fn named_list(naming: &amg_doc::BodyNaming, kind: TopoKind) -> Option<&[TopoName]> {
    match kind {
        TopoKind::Face => Some(&naming.faces),
        TopoKind::Edge => Some(&naming.edges),
        TopoKind::Vertex => Some(&naming.vertices),
        TopoKind::FaceGroup => None,
    }
}

/// R1 (provisional): the persistent reference of sub-entity `(kind, index)` of `body` in
/// `eval`. `None` if the body is missing or the element has no name (a B-rep body without
/// naming, an implicit or form body, an index out of range).
pub fn topo_ref_at(eval: &Evaluated, body: BodyId, kind: TopoKind, index: u32) -> Option<TopoRef> {
    let b = eval.body(body)?;
    if let Some(name) = b
        .naming
        .as_deref()
        .and_then(|n| named_list(n, kind))
        .and_then(|l| l.get(index as usize))
    {
        return Some(TopoRef {
            body,
            kind,
            name: name.clone(),
            fingerprint: None,
        });
    }
    let BodyGeom::Mesh(mesh) = &b.geom else {
        return None;
    };
    Some(TopoRef {
        body,
        kind,
        fingerprint: Some(mesh_fingerprint(mesh, kind, index)?),
        name: provisional_name(body, kind, index)?,
    })
}

/// R2 (provisional): the current index of a referenced sub-entity, or `None` when it no
/// longer resolves (body gone, name gone, mesh element changed).
pub fn resolve_topo(eval: &Evaluated, r: &TopoRef) -> Option<u32> {
    let b = eval.body(r.body)?;
    if let Some(list) = b.naming.as_deref().and_then(|n| named_list(n, r.kind))
        && let Some(i) = list.iter().position(|n| *n == r.name)
    {
        return u32::try_from(i).ok();
    }
    let BodyGeom::Mesh(mesh) = &b.geom else {
        return None;
    };
    let index = provisional_index(&r.name, r.body, r.kind)?;
    let now = mesh_fingerprint(mesh, r.kind, index)?;
    r.fingerprint
        .as_ref()
        .is_none_or(|f| *f == now)
        .then_some(index)
}

#[cfg(test)]
mod tests {
    use super::*;
    use amg_doc::{ComponentId, EvalBody, FeatureId, Revision};
    use std::sync::Arc;

    fn mesh(z: f64) -> IndexedMesh {
        IndexedMesh::new(
            vec![
                Point3::new(0.0, 0.0, z),
                Point3::new(1.0, 0.0, z),
                Point3::new(0.0, 1.0, z),
                Point3::new(1.0, 1.0, z),
            ],
            vec![[0, 1, 2], [1, 3, 2]],
        )
        .unwrap()
    }

    fn eval_with(m: IndexedMesh) -> (Evaluated, BodyId) {
        let id = BodyId {
            origin: FeatureId(7),
            slot: 0,
        };
        let mut e = Evaluated::new(Revision(1));
        e.set_body(
            id,
            Arc::new(EvalBody {
                component: ComponentId(1),
                geom: BodyGeom::Mesh(Arc::new(m)),
                naming: None,
            }),
        );
        (e, id)
    }

    #[test]
    fn mesh_refs_round_trip_and_drop_when_the_element_changes() {
        let (e, body) = eval_with(mesh(0.0));
        for (kind, index) in [
            (TopoKind::Face, 1),
            (TopoKind::Edge, 4),
            (TopoKind::Vertex, 3),
        ] {
            let r = topo_ref_at(&e, body, kind, index).unwrap();
            assert_eq!(resolve_topo(&e, &r), Some(index));
            let json = serde_json::to_string(&r).unwrap();
            let back: TopoRef = serde_json::from_str(&json).unwrap();
            assert_eq!(resolve_topo(&e, &back), Some(index), "{kind:?} after serde");
        }
        assert!(topo_ref_at(&e, body, TopoKind::Face, 2).is_none());
        let r = topo_ref_at(&e, body, TopoKind::Face, 0).unwrap();
        let (moved, _) = eval_with(mesh(1.0));
        assert_eq!(
            resolve_topo(&moved, &r),
            None,
            "moved triangle is not matched"
        );
    }
}
